//! The block tiles, and the texture the chunk shader samples them from.
//!
//! The art lives in one atlas PNG, [`ATLAS_PATH`]: a single row of
//! [`TILE_SIZE`]-pixel square tiles in [`Tile`] order. The art is placeholder,
//! generated by `scripts/placeholder-textures.py`, which must use the same
//! order.
//!
//! [`build`] turns the atlas into a 2D array texture with one layer per tile
//! and a full mip chain per layer. Layers instead of one big atlas, so smaller
//! mips never blend a tile with its neighbour. Mips are box-filtered in linear
//! color, so a distant checkerboard of black and white averages to the right
//! mid grey instead of a too-dark one. (Bevy 0.20's GPU mip generation needs
//! a storage-capable format, which sRGB RGBA8 isn't, and these mips only
//! need building when the atlas changes.)

use bevy::{
    asset::RenderAssetUsages,
    image::{ImageAddressMode, ImageSampler, ImageSamplerDescriptor},
    prelude::*,
    render::render_resource::{
        Extent3d, TextureDataOrder, TextureDimension, TextureFormat, TextureViewDescriptor,
        TextureViewDimension,
    },
};

/// The block atlas, relative to `assets/`.
pub const ATLAS_PATH: &str = "textures/blocks.png";
/// Width and height of one tile, in pixels.
pub const TILE_SIZE: u32 = 16;
/// Anisotropic filtering samples at most. Keeps textures sharp on surfaces
/// seen at a grazing angle, where plain mipmapping would blur them.
const MAX_ANISOTROPY: u16 = 16;

/// One tile of the block atlas.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tile {
    Stone,
    Dirt,
    GrassTop,
    GrassSide,
}

impl Tile {
    /// Every tile, in atlas order.
    pub const ALL: [Tile; 4] = [Tile::Stone, Tile::Dirt, Tile::GrassTop, Tile::GrassSide];
    /// Tiles in the atlas.
    pub const COUNT: usize = Self::ALL.len();

    /// The tile's position in the atlas, left to right, which is also its
    /// layer in the block texture. Exhaustive, so a new tile can't compile
    /// without a place in the atlas.
    pub fn layer(self) -> u32 {
        match self {
            Tile::Stone => 0,
            Tile::Dirt => 1,
            Tile::GrassTop => 2,
            Tile::GrassSide => 3,
        }
    }
}

/// Builds the block texture from `atlas`, a single row of [`Tile::COUNT`]
/// square tiles of [`TILE_SIZE`] pixels in sRGB RGBA8.
pub fn build(atlas: &Image) -> Result<Image, String> {
    let layers = Tile::COUNT as u32;
    let format = atlas.texture_descriptor.format;
    if format != TextureFormat::Rgba8UnormSrgb {
        return Err(format!("atlas must be Rgba8UnormSrgb, not {format:?}"));
    }
    let (width, height) = (atlas.width(), atlas.height());
    if (width, height) != (TILE_SIZE * layers, TILE_SIZE) {
        return Err(format!(
            "atlas is {width}×{height}, expected {layers} tiles of {TILE_SIZE}×{TILE_SIZE} in a row"
        ));
    }
    let pixels = atlas.data.as_deref().ok_or("atlas has no pixel data")?;

    let mut data = Vec::new();
    for layer in 0..layers {
        let mut level = tile(pixels, width, layer);
        let mut size = TILE_SIZE;
        // Layer-major: every mip of this layer, largest first.
        data.extend_from_slice(&level);
        while size > 1 {
            level = downsample(&level, size);
            size /= 2;
            data.extend_from_slice(&level);
        }
    }

    let mut image = Image::new_uninit(
        Extent3d {
            width: TILE_SIZE,
            height: TILE_SIZE,
            depth_or_array_layers: layers,
        },
        TextureDimension::D2,
        TextureFormat::Rgba8UnormSrgb,
        RenderAssetUsages::RENDER_WORLD,
    );
    image.data = Some(data);
    image.data_order = TextureDataOrder::LayerMajor;
    image.texture_descriptor.mip_level_count = mip_levels(TILE_SIZE);
    image.texture_view_descriptor = Some(TextureViewDescriptor {
        dimension: Some(TextureViewDimension::D2Array),
        ..default()
    });
    image.sampler = ImageSampler::Descriptor(sampler());
    Ok(image)
}

/// Mip levels for a square texture of `size` pixels, down to 1×1.
pub fn mip_levels(size: u32) -> u32 {
    size.ilog2() + 1
}

/// Trilinear and anisotropic filtering, clamped at tile edges. Linear
/// magnification would blur close-up pixels, so the shader snaps its UVs to
/// texel centres and only blends across the one screen pixel at each texel
/// edge.
fn sampler() -> ImageSamplerDescriptor {
    let mut sampler = ImageSamplerDescriptor::default();
    sampler
        .set_address_mode(ImageAddressMode::ClampToEdge)
        .set_anisotropic_filter(MAX_ANISOTROPY);
    sampler
}

/// Copies tile `index` out of a row of tiles `width` pixels wide.
fn tile(pixels: &[u8], width: u32, index: u32) -> Vec<u8> {
    let row_bytes = (TILE_SIZE * 4) as usize;
    (0..TILE_SIZE)
        .flat_map(|y| {
            let start = ((y * width + index * TILE_SIZE) * 4) as usize;
            &pixels[start..start + row_bytes]
        })
        .copied()
        .collect()
}

/// Halves a square sRGB RGBA8 image, averaging each 2×2 block in linear
/// color. Alpha is linear already.
fn downsample(pixels: &[u8], size: u32) -> Vec<u8> {
    let half = size / 2;
    let mut out = Vec::with_capacity((half * half * 4) as usize);
    for y in 0..half {
        for x in 0..half {
            for channel in 0..4 {
                let mut sum = 0.0;
                for (dx, dy) in [(0, 0), (1, 0), (0, 1), (1, 1)] {
                    let i = (((2 * y + dy) * size + 2 * x + dx) * 4 + channel) as usize;
                    let value = pixels[i] as f32 / 255.0;
                    sum += if channel == 3 {
                        value
                    } else {
                        Srgba::gamma_function(value)
                    };
                }
                let mean = sum / 4.0;
                let value = if channel == 3 {
                    mean
                } else {
                    Srgba::gamma_function_inverse(mean)
                };
                out.push((value * 255.0).round() as u8);
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use bevy::image::{CompressedImageFormats, ImageFilterMode, ImageType};

    /// An atlas whose tile `i` is filled by `paint(i, x, y)`.
    fn atlas(paint: impl Fn(u32, u32, u32) -> [u8; 4]) -> Image {
        let width = TILE_SIZE * Tile::COUNT as u32;
        let data = (0..TILE_SIZE)
            .flat_map(|y| (0..width).map(move |x| (x, y)))
            .flat_map(|(x, y)| paint(x / TILE_SIZE, x % TILE_SIZE, y))
            .collect();
        Image::new(
            Extent3d {
                width,
                height: TILE_SIZE,
                depth_or_array_layers: 1,
            },
            TextureDimension::D2,
            data,
            TextureFormat::Rgba8UnormSrgb,
            RenderAssetUsages::all(),
        )
    }

    /// Byte offset of (layer, mip) in layer-major data.
    fn offset(layer: u32, mip: u32) -> usize {
        let per_layer: u32 = (0..mip_levels(TILE_SIZE))
            .map(|m| (TILE_SIZE >> m).pow(2) * 4)
            .sum();
        let before: u32 = (0..mip).map(|m| (TILE_SIZE >> m).pow(2) * 4).sum();
        (layer * per_layer + before) as usize
    }

    /// The RGBA bytes of pixel (x, y) of (layer, mip).
    fn pixel(image: &Image, layer: u32, mip: u32, x: u32, y: u32) -> [u8; 4] {
        let at = offset(layer, mip) + ((y * (TILE_SIZE >> mip) + x) * 4) as usize;
        image.data.as_ref().unwrap()[at..at + 4].try_into().unwrap()
    }

    #[test]
    fn tile_layers_follow_atlas_order() {
        for (index, tile) in Tile::ALL.iter().enumerate() {
            assert_eq!(tile.layer(), index as u32);
        }
    }

    #[test]
    fn sixteen_pixels_make_five_mips() {
        assert_eq!(mip_levels(16), 5);
        assert_eq!(mip_levels(1), 1);
    }

    #[test]
    fn layers_hold_their_own_tile_and_full_mip_chains() {
        let image = build(&atlas(|i, _, _| [i as u8 * 50, 7, 9, 255])).unwrap();
        let size = image.texture_descriptor.size;
        assert_eq!(
            (size.width, size.height, size.depth_or_array_layers),
            (16, 16, 4)
        );
        assert_eq!(image.texture_descriptor.mip_level_count, 5);
        assert_eq!(
            image.texture_descriptor.format,
            TextureFormat::Rgba8UnormSrgb
        );
        assert_eq!(image.data_order, TextureDataOrder::LayerMajor);
        assert_eq!(image.data.as_ref().unwrap().len(), offset(4, 0));
        for layer in 0..4 {
            for mip in 0..5 {
                assert_eq!(
                    pixel(&image, layer, mip, 0, 0),
                    [layer as u8 * 50, 7, 9, 255]
                );
            }
        }
    }

    #[test]
    fn tile_pixels_keep_their_positions() {
        let image = build(&atlas(|i, x, y| [i as u8, x as u8, y as u8, 255])).unwrap();
        assert_eq!(pixel(&image, 1, 0, 5, 11), [1, 5, 11, 255]);
    }

    /// Mips shrink the tile, they don't flip or transpose it: a tile that's
    /// white on the left and black on the right stays that way.
    #[test]
    fn mips_keep_the_tile_the_right_way_round() {
        let image = build(&atlas(|_, x, _| {
            let v = if x < TILE_SIZE / 2 { 255 } else { 0 };
            [v, v, v, 255]
        }))
        .unwrap();
        for mip in 1..4 {
            let last = (TILE_SIZE >> mip) - 1;
            assert_eq!(pixel(&image, 0, mip, 0, last)[0], 255, "mip {mip}");
            assert_eq!(pixel(&image, 0, mip, last, 0)[0], 0, "mip {mip}");
        }
    }

    /// Black and white average to 50% linear light, which is about 188 in
    /// sRGB, not the naive 128.
    #[test]
    fn mips_average_in_linear_color() {
        let image = build(&atlas(|_, x, y| {
            let v = if (x + y).is_multiple_of(2) { 255 } else { 0 };
            [v, v, v, 255]
        }))
        .unwrap();
        for mip in 1..5 {
            assert_eq!(
                pixel(&image, 0, mip, 0, 0),
                [188, 188, 188, 255],
                "mip {mip}"
            );
        }
    }

    #[test]
    fn samples_with_mipmaps_and_anisotropy_clamped_to_each_tile() {
        let image = build(&atlas(|_, _, _| [0; 4])).unwrap();
        let ImageSampler::Descriptor(sampler) = image.sampler else {
            panic!("no sampler");
        };
        assert_eq!(sampler.anisotropy_clamp, MAX_ANISOTROPY);
        assert_eq!(sampler.mipmap_filter, ImageFilterMode::Linear);
        assert_eq!(sampler.address_mode_u, ImageAddressMode::ClampToEdge);
        assert_eq!(sampler.address_mode_v, ImageAddressMode::ClampToEdge);
        assert!(sampler.lod_max_clamp >= mip_levels(TILE_SIZE) as f32);
        let view = image.texture_view_descriptor.unwrap();
        assert_eq!(view.dimension, Some(TextureViewDimension::D2Array));
    }

    #[test]
    fn rejects_atlases_of_the_wrong_size() {
        let mut small = atlas(|_, _, _| [0; 4]);
        small.resize(Extent3d {
            width: TILE_SIZE * 3,
            height: TILE_SIZE,
            depth_or_array_layers: 1,
        });
        assert!(build(&small).is_err());
    }

    /// The real atlas file decodes the way the game loads it and builds.
    #[test]
    fn atlas_on_disk_builds() {
        let bytes = std::fs::read(format!("assets/{ATLAS_PATH}")).unwrap();
        let image = Image::from_buffer(
            &bytes,
            ImageType::Extension("png"),
            CompressedImageFormats::NONE,
            true,
            ImageSampler::Default,
            RenderAssetUsages::all(),
        )
        .unwrap();
        build(&image).unwrap();
    }
}
